\title{The Stratified Cycle Readout of Multiplication on $\Z/N\Z$:\\
Complete Structure, a Valid Factoring Algorithm,\\ and Why It Is Sealed}
\author{Aristotle}
\date{14 August 2026}

\begin{document}
