"""
Demo: escaping lcm-blindness -- an exhaustive search for multiplier pairs that
the unit group cannot tell apart but the stratified readout can.

For a semiprime N = p*q we scan all pairs (a, b) of multipliers with
ord_N(a) = ord_N(b) -- i.e. pairs that every probe confined to the unit group
reports as identical -- and check whether their full cycle spectra on Z/NZ
differ.  The theory predicts that a difference occurs precisely when the
individual prime orders differ, since the readout displays ord_p and ord_q as
separate cycle lengths while the unit group only sees their lcm.

The script also confirms, for each such separating pair, that the parity bit of
the readout matches the Jacobi symbol -- so even where the readout separates
multipliers, its coarsest summary remains a factorisation-free quantity.
"""

from __future__ import annotations

from math import gcd
from typing import Dict, List, Tuple


def euler_phi(n: int) -> int:
    result, m, d = n, n, 2
    while d * d <= m:
        if m % d == 0:
            while m % d == 0:
                m //= d
            result -= result // d
        d += 1
    if m > 1:
        result -= result // m
    return result


def multiplicative_order(a: int, n: int) -> int:
    if n == 1:
        return 1
    a %= n
    k, cur = 1, a
    while cur != 1:
        cur = (cur * a) % n
        k += 1
    return k


def divisors(n: int) -> List[int]:
    return sorted(d for d in range(1, n + 1) if n % d == 0)


def readout(n: int, a: int) -> Tuple[Tuple[int, int], ...]:
    """The stratified readout: ((stratum label, cycle length), ...)."""
    return tuple((d, multiplicative_order(a, n // d) if n // d > 1 else 1)
                 for d in divisors(n))


def cycle_count(n: int, a: int) -> int:
    return sum(euler_phi(n // d) // (multiplicative_order(a, n // d) if n // d > 1 else 1)
               for d in divisors(n))


def jacobi_symbol(a: int, n: int) -> int:
    a %= n
    result = 1
    while a:
        while a % 2 == 0:
            a //= 2
            if n % 8 in (3, 5):
                result = -result
        a, n = n, a
        if a % 4 == 3 and n % 4 == 3:
            result = -result
        a %= n
    return result if n == 1 else 0


def scan(p: int, q: int, show: int = 6) -> None:
    n = p * q
    units = [a for a in range(1, n) if gcd(a, n) == 1]
    by_order: Dict[int, List[int]] = {}
    for a in units:
        by_order.setdefault(multiplicative_order(a, n), []).append(a)

    separating: List[Tuple[int, int, int]] = []
    for L, group in by_order.items():
        for i, a in enumerate(group):
            for b in group[i + 1:]:
                if readout(n, a) != readout(n, b):
                    separating.append((L, a, b))

    total_pairs = sum(len(g) * (len(g) - 1) // 2 for g in by_order.values())
    print(f"N = {p}*{q} = {n}")
    print(f"  units: {len(units)}; pairs with equal ord_N: {total_pairs}")
    print(f"  pairs the stratified readout separates: {len(separating)}"
          f"  ({100 * len(separating) / max(total_pairs, 1):.1f}%)")
    for L, a, b in separating[:show]:
        ca, cb = cycle_count(n, a), cycle_count(n, b)
        print(f"    ord_N = {L:>3}: a = {a:>4} vs b = {b:>4}   "
              f"ord_p = {multiplicative_order(a, p)}/{multiplicative_order(b, p)}, "
              f"ord_q = {multiplicative_order(a, q)}/{multiplicative_order(b, q)}   "
              f"cycles {ca} vs {cb}")
        for m in (a, b):
            c = cycle_count(n, m)
            assert ((n - c) % 2 == 0) == (jacobi_symbol(m, n) == 1)
    print("  every separating multiplier still obeys the free sign law "
          "(parity of N - #cycles = Jacobi symbol)")


if __name__ == "__main__":
    for p, q in [(5, 13), (7, 11), (11, 13), (13, 17)]:
        scan(p, q)
        print()

