"""Algorithm D -- Polynomial-Time Prediction of the Permutation Sign.

The sign of a permutation of an N-element set with C cycles is (-1)^(N - C), so
the parity of N - C(N, a) is the coarsest summary of the whole cycle spectrum.
The complete sign law says this bit is *free*:

    N odd   :  even  <=>  Jacobi symbol J(a | N) = +1
    N even  :  even  <=>  ( 4 | N  =>  a = 1 mod 4 )

and, for the enlarged families,

    affine  :  sign(x -> a*x + b) = sign(x -> a*x) * sign(x -> x + b),
               the translation contributing parity of N - gcd(N, b)
    power   :  x -> x^k on Z/pZ is even  <=>  ( 4 | p-1  =>  k = 1 mod 4 )

Each prediction costs O(log^2 N) bit operations and needs no factorisation: a
global invariant of a permutation on N points, computed without touching it.
"""

from __future__ import annotations

from math import gcd
from typing import Literal


def jacobi_symbol(a: int, n: int) -> int:
    """Jacobi symbol (a | n) for odd n >= 1, via quadratic reciprocity."""
    assert n >= 1 and n % 2 == 1
    a %= n
    result = 1
    while a:
        while a % 2 == 0:
            a //= 2
            if n % 8 in (3, 5):
                result = -result
        a, n = n, a
        if a % 4 == 3 and n % 4 == 3:
            result = -result
        a %= n
    return result if n == 1 else 0


def multiplicative_sign(a: int, n: int) -> Literal[1, -1]:
    """Sign of x -> a*x on Z/nZ, predicted in polynomial time."""
    assert gcd(a, n) == 1
    if n % 2 == 1:
        return 1 if jacobi_symbol(a, n) == 1 else -1
    return 1 if (n % 4 != 0 or a % 4 == 1) else -1


def translation_sign(b: int, n: int) -> Literal[1, -1]:
    """Sign of x -> x + b on Z/nZ: it has exactly gcd(n, b) cycles."""
    return 1 if (n - gcd(n, b)) % 2 == 0 else -1


def affine_sign(a: int, b: int, n: int) -> Literal[1, -1]:
    """Sign of x -> a*x + b on Z/nZ, by the affine sign law."""
    return multiplicative_sign(a, n) * translation_sign(b, n)


def power_map_sign(k: int, p: int) -> Literal[1, -1]:
    """Sign of x -> x^k on Z/pZ (p an odd prime, gcd(k, p-1) = 1)."""
    assert gcd(k, p - 1) == 1
    return 1 if ((p - 1) % 4 != 0 or k % 4 == 1) else -1


def _brute_sign(f, n: int) -> int:
    seen = bytearray(n)
    cycles = 0
    for s in range(n):
        if seen[s]:
            continue
        cycles += 1
        x = s
        while not seen[x]:
            seen[x] = 1
            x = f(x)
    return 1 if (n - cycles) % 2 == 0 else -1


if __name__ == "__main__":
    for n in [15, 21, 65, 143, 12, 20, 22]:
        for a in range(1, n):
            if gcd(a, n) != 1:
                continue
            assert multiplicative_sign(a, n) == _brute_sign(lambda x: (a * x) % n, n)
            for b in range(n):
                assert affine_sign(a, b, n) == _brute_sign(
                    lambda x: (a * x + b) % n, n)
        print(f"N = {n:>4}: multiplicative and affine sign laws verified for all a, b")
    for p in [7, 11, 13, 17, 19]:
        for k in range(1, p - 1):
            if gcd(k, p - 1) == 1:
                assert power_map_sign(k, p) == _brute_sign(lambda x: pow(x, k, p), p)
        print(f"p = {p:>3}: power-map sign law verified for all admissible k")
